const D = { energy: .6, scale: 1, speed: 1, density: .5, rayleigh: .55, hexa: .5, relief: .6, hue: 26, x: .5, y: .5, style: 'convection', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Rayleigh-Benard convection, seen from above, via the Swift-Hohenberg equation — the
// amplitude equation RB reduces to near onset:
//        du/dt = r*u - (1 + lap)^2 u + g*u^2 - u^3
// The quadratic term breaks up/down symmetry and selects HEXAGONS (the iconic Benard cell);
// without it the pattern is rolls. Between them lies spiral-defect chaos, which never
// settles — grain boundaries glide, defects nucleate and annihilate forever. ----
const BW = 164, BH = Math.max(72, Math.round(BW * height / width));
const N = BW * BH;
if (!S.g || S.bw !== BW || S.bh !== BH) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH;
  S.U = new Float32Array(N); S.L1 = new Float32Array(N); S.L2 = new Float32Array(N);
  S.U2 = new Float32Array(N); S.init = false;
}

const sd = P.seed | 0;
function hsh(ix, iy, iz) {
  let h = (Math.imul(ix, 374761393) + Math.imul(iy, 668265263) + Math.imul(iz, 1274126177) + Math.imul(sd, 1442695041)) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) | 0;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967295;   // >>> not >> : an arithmetic fold caps the hash at 0.5
}

if (!S.init || S.seedUsed !== P.seed) {
  S.init = true; S.seedUsed = P.seed;
  for (let i = 0; i < N; i++) S.U[i] = (hsh(i % BW, (i / BW) | 0, 1) - 0.5) * 0.5;
}

const tt = K.t;
const U = S.U, L1 = S.L1, L2 = S.L2;
// control parameter r ~ (Ra - Ra_c)/Ra_c : how far above the convection threshold we are.
// It breathes on incommensurate slow sines, so the pattern walks through regimes for minutes.
const rBase = -0.06 + P.rayleigh * 0.75;
const rWob = 0.11 * Math.sin(tt * 0.0231) + 0.06 * Math.sin(tt * 0.0517 + 1.9) + 0.03 * Math.sin(tt * 0.0894 + 0.6);
const r = rBase + rWob + K.swell * 0.02 + A.bass * 0.05;
const gq = (P.hexa * 1.5) * (0.85 + 0.15 * Math.sin(tt * 0.0413 + 2.4));   // hexagon selector
// q0 = the preferred wavenumber. Generalising (1+lap)^2 to (q0^2+lap)^2 lets the cell SIZE
// breathe, which is what a real Benard layer does as its depth/Rayleigh number changes.
// It is also the motion floor: a lattice that merely TRANSLATES is periodic, so it looks
// identical 8s later — only re-selecting the wavelength forces genuine reorganisation.
const q0 = 1 + 0.14 * (0.62 * Math.sin(tt * 0.0193) + 0.26 * Math.sin(tt * 0.0447 + 1.5) + 0.12 * Math.sin(tt * 0.0821 + 0.3));
const q02 = q0 * q0, q04 = q02 * q02;
// Explicit Euler on a 5-point stencil: lap has eigenvalues in [-8,0], so lap^2 reaches 64 and
// stability needs dt < 2/(64 - 16*q0^2 + q0^4 - r) ~ 0.038. Drive `speed` with step COUNT,
// never by enlarging dt — at dt=0.085 the grid-scale checkerboard mode amplifies 3.1x/step.
const dt = 0.030;
const steps = Math.max(1, Math.min(6, Math.round(1 + P.speed * 2)));
// a slow spatial ramp in r (a real cell is never heated perfectly evenly) — this is what
// nucleates the grain boundaries and keeps the defect dance alive
const rgx = 0.55 * Math.sin(tt * 0.0173 + 1.1), rgy = 0.55 * Math.cos(tt * 0.0209);
const rAmp = 0.10 * (0.3 + P.density);
const nz = (tt * 331.3) | 0;
const noiseAmp = 0.0035 + P.density * 0.010;

for (let st = 0; st < steps; st++) {
  // lap(u) -> L1  (periodic)
  for (let j = 0; j < BH; j++) {
    const jm = ((j - 1 + BH) % BH) * BW, jp = ((j + 1) % BH) * BW, jc = j * BW;
    for (let i = 0; i < BW; i++) {
      const im = (i - 1 + BW) % BW, ip = (i + 1) % BW;
      L1[jc + i] = U[jc + im] + U[jc + ip] + U[jm + i] + U[jp + i] - 4 * U[jc + i];
    }
  }
  // lap(lap(u)) -> L2
  for (let j = 0; j < BH; j++) {
    const jm = ((j - 1 + BH) % BH) * BW, jp = ((j + 1) % BH) * BW, jc = j * BW;
    for (let i = 0; i < BW; i++) {
      const im = (i - 1 + BW) % BW, ip = (i + 1) % BW;
      L2[jc + i] = L1[jc + im] + L1[jc + ip] + L1[jm + i] + L1[jp + i] - 4 * L1[jc + i];
    }
  }
  // du/dt = r*u - (q0^2 + lap)^2 u + g*u^2 - u^3
  //       = r*u - q0^4*u - 2*q0^2*lap(u) - lap^2(u) + g*u^2 - u^3
  for (let j = 0; j < BH; j++) {
    const jc = j * BW;
    const ry = (j / BH - 0.5);
    for (let i = 0; i < BW; i++) {
      const p = jc + i;
      const u = U[p];
      const rloc = r + rAmp * ((i / BW - 0.5) * rgx + ry * rgy) * 2;
      let v = u + dt * (rloc * u - q04 * u - 2 * q02 * L1[p] - L2[p] + gq * u * u - u * u * u);
      U[p] = v < -3 ? -3 : (v > 3 ? 3 : v);
    }
  }
}
// thermal fluctuation once per frame — keeps defects nucleating so the field never freezes
for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) {
  U[j * BW + i] += (hsh(i, j, nz) - 0.5) * noiseAmp * 2;
}

// ---- large-scale circulation: a real Benard cell always has a mean flow that advects the
// rolls bodily. Without it Swift-Hohenberg ANNEALS to a near-stationary lattice and reads
// STATIC on the 8s gate no matter how busy the defects look. Translation + rotation on
// incommensurate rates, so the frame never repeats. Bilinear resampling costs a little
// amplitude, which the SH instability immediately regrows — it self-sharpens. ----
const mf = 0.014 * (0.3 + P.speed * 0.7);
const mfx = mf * (1.7 * Math.sin(tt * 0.037) + 0.8 * Math.sin(tt * 0.091 + 1.3) + 0.4 * Math.sin(tt * 0.211));
const mfy = mf * (1.4 * Math.cos(tt * 0.053) + 0.7 * Math.sin(tt * 0.113 + 0.6) + 0.3 * Math.sin(tt * 0.179 + 2.2));
const mrot = 0.00042 * (0.3 + P.speed * 0.7) * (Math.sin(tt * 0.0271 + 0.9) + 0.5 * Math.sin(tt * 0.0673));
const U2 = S.U2;
for (let j = 0; j < BH; j++) {
  const ry = j - BH * 0.5;
  for (let i = 0; i < BW; i++) {
    const rx = i - BW * 0.5;
    let bx = i - (mfx - ry * mrot), by = j - (mfy + rx * mrot);
    bx = ((bx % BW) + BW) % BW; by = ((by % BH) + BH) % BH;
    const x0 = bx | 0, y0 = by | 0, fx = bx - x0, fy = by - y0;
    const x1 = (x0 + 1) % BW, y1 = (y0 + 1) % BH;
    const a = U[y0 * BW + x0], b2 = U[y0 * BW + x1], c = U[y1 * BW + x0], d2 = U[y1 * BW + x1];
    const top = a + (b2 - a) * fx, bot = c + (d2 - c) * fx;
    U2[j * BW + i] = top + (bot - top) * fy;
  }
}
U.set(U2);

// ---- render ----
const g = S.g; g.loadPixels(); const px = g.pixels;
const sec = K.section | 0;
const style = P.style;
const hb = ((P.hue + sec * 12 + Math.sin(tt * 0.0161) * 15) % 360 + 360) % 360;
const gain = 0.5 + P.energy * 1.25 + A.rms * 0.4;
const rel = P.relief;
function pal(m, sp, off) {
  const hr = hb / 360 + off;
  return [0.5 + 0.5 * Math.cos(6.2831 * (m + hr)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + hr + sp)),
          0.5 + 0.5 * Math.cos(6.2831 * (m + hr + sp * 2))];
}
for (let j = 0; j < BH; j++) {
  const jm = ((j - 1 + BH) % BH) * BW, jp = ((j + 1) % BH) * BW, jc = j * BW;
  for (let i = 0; i < BW; i++) {
    const im = (i - 1 + BW) % BW, ip = (i + 1) % BW;
    const p = jc + i;
    const u = U[p];
    const gx = U[jc + ip] - U[jc + im], gy = U[jp + i] - U[jm + i];
    // u > 0 = hot rising core, u < 0 = cool sinking rim
    const hot = Math.max(0, Math.min(1, 0.5 + u * 0.62));
    // relief: light the cell tops as rounded convection domes from upper-left
    const lit = 1 + (gx * 0.62 - gy * 0.36) * 2.0 * rel;
    let r2, gg, b;
    if (style === 'magma') {              // planetary mantle: dark crust, molten cracks between cells
      const crust = Math.max(0, Math.min(1, 0.55 - u * 0.7));
      const glow = Math.pow(Math.max(0, 1 - crust), 1.5) * gain;
      const cc = pal(0.02 + glow * 0.14, 0.11, 0.0);
      const bs = 0.055 + crust * 0.10;
      r2 = Math.min(1, bs + glow * cc[0] * 1.75 + glow * glow * 0.35);
      gg = Math.min(1, bs * 0.82 + glow * cc[1] * 1.15);
      b = Math.min(1, bs * 0.86 + glow * cc[2] * 0.55);
    } else if (style === 'bronze') {      // chiaroscuro relief only: hammered metal, no colour key
      const v = Math.max(0, Math.min(1, 0.42 + (gx * 0.66 - gy * 0.38) * 3.0 * (0.5 + rel) + u * 0.06));
      r2 = Math.min(1, v * 1.02 + 0.05); gg = Math.min(1, v * 0.90 + 0.04); b = Math.min(1, v * 0.66 + 0.05);
    } else if (style === 'blueprint') {   // schematic: iso-lines of the amplitude on drafting cyan
      const band = Math.abs(((u * 3.2 + 8) % 1) - 0.5);
      const ln = band < 0.085 ? 1 : 0;
      const base = 0.07 + hot * 0.09;
      r2 = base * 0.42 + ln * 0.34; gg = base * 0.76 + ln * 0.86; b = Math.min(1, base * 1.75 + ln * 1.0);
    } else if (style === 'ink') {         // sumi tonal wash on cream
      const ink = Math.max(0, Math.min(1, (0.5 - u * 0.55) * (0.6 + gain * 0.4)));
      const paper = 0.94 - ink * 0.84;
      r2 = paper * 0.99; gg = paper * 0.96; b = paper * 0.88;
    } else {                              // convection (default) — false-colour thermal cells
      const cc = pal(0.02 + hot * 0.42, 0.17, 0.0);
      const sh = (0.16 + hot * 0.80) * (0.6 + gain * 0.42);
      r2 = Math.min(1, cc[0] * sh * lit + hot * hot * 0.16);
      gg = Math.min(1, cc[1] * sh * lit + hot * hot * 0.12);
      b = Math.min(1, cc[2] * sh * lit + hot * hot * 0.10);
    }
    const o = 4 * p;
    px[o] = Math.max(0, Math.min(255, r2 * 255));
    px[o + 1] = Math.max(0, Math.min(255, gg * 255));
    px[o + 2] = Math.max(0, Math.min(255, b * 255));
    px[o + 3] = 255;
  }
}
g.updatePixels();

const z = Math.max(1, P.scale);
const sw = BW / z, sh = BH / z;
const sx = (BW - sw) * Math.min(1, Math.max(0, P.x)), sy = (BH - sh) * Math.min(1, Math.max(0, P.y));
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height, sx, sy, sw, sh);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
